from itertools import chain

def intersperse_list(numbers: List[int], delimeter: int) -> List[int]:
    """Intersperse a number 'delimeter' between every two consecutive elements of input list `numbers'
    >>> intersperse_list([], 4)
    []
    >>> intersperse_list([1, 2, 3], 4)
    [1, 4, 2, 4, 3]
    """

    return list(chain.from_iterable(
        [numbers[i - 1], delimeter] if i else [numbers[0], delimeter]
        for i in range(len(numbers))))


