    """ For a given list of input numbers, calculate Squared Mean Absolute Deviation
    around the mean of this dataset.
    Squared Mean Absolute Deviation is the average of the squared values for each
    element and a centerpoint (mean in this case):
    SMAAD = average (x - x_mean)**2
    >>> squared_mean_absolute_deviation([1.0, 2.0, 3.0, 4.0])
    1.0
    """
    total = 0
    for num in numbers:
        total += (num - mean(numbers)) ** 2

    return total / len(numbers)

