def separate_braces_string(braces_string: str) -> str:
    """ Input to this function is a string containing multiple groups of nested braces in the format '{(' followed by either '
     ')' or a opening brace '(' and so on till you end up with nothing left.
    >>> separate_braces_string('( ( ) ) { () ) ( ) } { }')
    '{({})}'
